42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
